def build():
 OUT.mkdir(parents=True,exist_ok=True)
 fonts=Path('/usr/share/fonts/truetype/dejavu')
 for name,file in [('Guide','DejaVuSans.ttf'),('GuideBold','DejaVuSans-Bold.ttf')]:pdfmetrics.registerFont(TTFont(name,str(fonts/file)))
 rows=[]
 for line in (OUT/'screen-guide.tsv').read_text().splitlines():
  if not line or line.startswith('#'):continue
  key,route,body,warning=line.split('|');rows.append(dict(key=key,route=route,body=body,warning=warning))
 assert len(rows)==92 and len({r['key'] for r in rows})==92
 images={}
 for r in rows:
  candidates=list(CAP.rglob(r['key']+'.jpg'));assert candidates,r['key']
  images[r['key']]=min(candidates,key=lambda p:(0 if p.parent.name=='current-api36' else 1,len(str(p))))
 assert {p.stem for p in CAP.rglob('*.jpg')}==set(images),'An evidence screen lacks documentation'
 target=OUT/'MyNotes-Illustrated-User-Guide.pdf';c=Canvas(str(target),pagesize=(595.28,841.89),pageCompression=1,invariant=1)
 c.setTitle('MyNotes - Illustrated User Guide and Screen Reference');c.setAuthor('MyNotes project');c.setSubject('116-page working edition; source-pinned synthetic screens; offline, searchable PDF')
 ink=HexColor('#20242c');muted=HexColor('#525b69');gold=HexColor('#87632b');blue=HexColor('#245d91')
 style=ParagraphStyle('body',fontName='Guide',fontSize=10.2,leading=15,textColor=ink,spaceAfter=10)
 def paragraph(text,x,y,width,small=False):
  ps=style if not small else ParagraphStyle('small',parent=style,fontSize=8.6,leading=12)
  q=Paragraph(escape(text).replace('\n','<br/><br/>'),ps);w,h=q.wrap(width,800);assert y-h>=48,(c.getPageNumber(),y,h,text[:60]);q.drawOn(c,x,y-h);return y-h-12
 def base(title,subtitle,key):
  c.bookmarkPage(key);c.addOutlineEntry(title,key,level=0,closed=False)
  c.setFillColor(ink);c.rect(0,782,595.28,60,fill=1,stroke=0);c.setFillColor(HexColor('#ead1a2'));c.setFont('GuideBold',10);c.drawString(32,808,'MYNOTES  /  USER GUIDE + SCREEN REFERENCE')
  c.setFillColor(muted);c.setFont('Guide',8);c.drawString(32,28,'Working edition • 03 Nov 2026 • Offline PDF • Candidate features are not acceptance claims')
  c.drawRightString(563,28,f'{c.getPageNumber()} / 116')
  c.setFillColor(ink);c.setFont('GuideBold',21)
  for i,line in enumerate(textwrap.wrap(title,39)):c.drawString(32,747-i*27,line)
  c.setFillColor(blue);c.setFont('Guide',9)
  for i,line in enumerate(textwrap.wrap(subtitle,94)):c.drawString(32,690-i*13,line)
  return 652
 def heading(text,x,y):c.setFillColor(gold);c.setFont('GuideBold',10);c.drawString(x,y,text.upper());return y-16
 base('Your notes. Your device.','A detailed illustrated handbook •116 pages •92 source-pinned screen frames','cover')
 y=paragraph('A practical guide to navigation, writing, formatting, structured content, capture, files, folders, voice and recovery. Actual synthetic app screens are paired with routes, procedures and limitations. This is a PDF design/reference document, not an editable Figma project.',32,626,530)
 y=paragraph('Read the boundaries before trying candidate features. Current physical reports take priority over optimistic automated conclusions. No claim is made that all pending issues or the requested360–480-minute work target are complete.',32,y-12,530)
 c.setFillColor(ink);c.roundRect(32,175,531,185,16,fill=1,stroke=0);c.setFillColor(white);c.setFont('GuideBold',18);c.drawString(54,319,'Open this PDF in MyNotes')
 c.setFont('Guide',12)
 for i,line in enumerate(['1  Save the PDF to local device storage.','2  Home > Library > Open file.','3  Select MyNotes-Illustrated-User-Guide.pdf.','4  Scroll, Find, Go to page, or use Page text.']):c.drawString(54,282-i*25,line)
 c.showPage()
 for index,(title,subtitle,text) in enumerate(FRONT):
  y=base(title,subtitle,'front'+str(index))
  if title.startswith('Contents '):
   part=int(title[-1])-1
   for j,r in enumerate(rows[part*32:(part+1)*32]):
    n=part*32+j+1;label=f'{n:02d}  '+r['key'].replace('-',' ').title();c.setFillColor(blue);c.setFont('Guide',9.5);c.drawString(35,y,label);c.drawRightString(560,y,str(24+n));c.linkRect('',f'screen-{n}',(32,y-3,563,y+11),relative=0,thickness=0);y-=18
  else:
   for section in text.split('\n'):y=paragraph(section,32,y,531)
  c.showPage()
 for n,r in enumerate(rows,1):
  title=r['key'].replace('-',' ').title();y=base(f'{n:02d} / {title}',r['route'],f'screen-{n}')
  path=images[r['key']];image=ImageReader(str(path));iw,ih=image.getSize();w=min(230,450*iw/ih);h=w*ih/iw;x=563-w
  c.setFillColor(HexColor('#f0f2f5'));c.roundRect(x-7,y-h-7,w+14,h+14,9,fill=1,stroke=0);c.drawImage(image,x,y-h,w,h,preserveAspectRatio=True)
  textwidth=x-48;ytext=heading('What this screen does',32,y)
  ytext=paragraph(r['body'],32,ytext,textwidth)
  ytext=heading('Before you act',32,ytext-8);ytext=paragraph('Follow the route above and check the current note, workspace, selection and open panel. A local object action is different from a note-wide or library-wide operation. Use Cancel or Back if the target is wrong.',32,ytext,textwidth)
  ytext=heading('Important boundary',32,ytext-8);ytext=paragraph(r['warning'],32,ytext,textwidth)
  bottom=min(y-h,ytext)-22
  bottom=heading('Verify the result',32,bottom)
  bottom=paragraph('Inspect the intended change and the neighbouring content. Where the action saves or moves data, re-open the affected item and check the saved state. Preserve originals and use the documented recovery/export route before destructive changes. Report the actual entry path and visible failure; a screenshot alone is not full validation.',32,bottom,531,True)
  c.setFont('Guide',7);c.setFillColor(muted)
  c.drawString(32,55,'Image: synthetic code41 fixture • run41503575601 • '+path.parent.name+' • '+r['key'])
  c.showPage()
 c.save()
 reader=PdfReader(str(target));assert len(reader.pages)==116
 counts=[len(p.extract_text()) for p in reader.pages];assert min(counts)>200
 assert not reader.is_encrypted and target.stat().st_size<32*1024*1024
 metadata=dict(schema=1,pages=len(reader.pages),screen_frames=len(rows),source_run=41503575601,source_commit='c463ece1d8114a855d00a135c8532ac7100dfe7a',screens='synthetic fixtures only, code41; NOT a green complete workflow',candidate_features='42/43, qualification pending',sha256=hashlib.sha256(target.read_bytes()).hexdigest(),bytes=target.stat().st_size,minimum_page_text_characters=min(counts),total_extracted_characters=sum(counts),android_open_validation='pending exact-byte native check',frames=[dict(key=r['key'],page=25+i,image_sha256=hashlib.sha256(images[r['key']].read_bytes()).hexdigest()) for i,r in enumerate(rows)])
 (OUT/'guide-manifest.json').write_text(json.dumps(metadata,indent=2)+'\n');print(json.dumps({k:v for k,v in metadata.items() if k!='frames'},indent=2))
